// Read-only public GitHub metadata for the PLAY-04 merge runs at 4dea392. No logs/artifacts downloaded.
const root = 'https://api.github.com/repos/chroniicallydiistracted/lorcana-online-tcg/actions/runs/';
const get = async path => { const r = await fetch(root + path, { headers: { Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' }, signal: AbortSignal.timeout(15000) }); if (!r.ok) throw new Error('metadata unavailable ' + r.status); return r.json(); };
const sha = '4dea392d382c950a7efa66a467a15018d3ec08a0';
for (const [id, branch] of [['39108811073', 'claude/play-04-opening-fix-audit'], ['39109642662', 'main']]) {
  const run = await get(id), jobs = await get(id + '/jobs?per_page=100');
  if (run.id !== Number(id) || run.head_sha !== sha || run.head_branch !== branch || run.status !== 'completed' || run.conclusion !== 'success') throw new Error('Unexpected hosted result ' + id);
  const steps = jobs.jobs.flatMap(j => j.steps.map(s => s.conclusion));
  if (jobs.total_count !== jobs.jobs.length || jobs.jobs.some(j => j.conclusion !== 'success') || steps.some(c => !['success', 'skipped'].includes(c))) throw new Error('Unexpected job/step result ' + id);
  console.log(JSON.stringify({ id, attempt: run.run_attempt, event: run.event, head_branch: run.head_branch, head_sha: run.head_sha, conclusion: run.conclusion, run_started_at: run.run_started_at, updated_at: run.updated_at, jobs: jobs.jobs.map(j => ({ name: j.name, conclusion: j.conclusion, started_at: j.started_at, completed_at: j.completed_at, steps: j.steps.map(s => s.name + ':' + s.conclusion) })) }));
}
